import {openCamera} from './camera.js';
import {meanRGB,compareRGB,remainingSeconds,clock} from './analysis.js';
const $=s=>document.querySelector(s);
const paths={menu:'M4 6h16M4 12h16M4 18h16',close:'M6 6l12 12M6 18L18 6',home:'M3 10l9-7 9 7v10H15v-6H9v6H3z',scan:'M8 3H4v5m12-5h4v5M4 16v5h4m12-5v5h-4',history:'M4 19V9m5 10V5m6 14v-7m5 7V3',lesions:'M8 3l4 1 4-1 3 4-1 4 2 4-4 4-4-1-4 2-4-4 1-4-2-4z',settings:'M19.02 9.09L19.43 10.40L21.59 10.56L21.59 13.44L19.43 13.60L19.02 14.91L18.38 16.12L19.80 17.76L17.76 19.80L16.12 18.38L14.91 19.02L13.60 19.43L13.44 21.59L10.56 21.59L10.40 19.43L9.09 19.02L7.88 18.38L6.24 19.80L4.20 17.76L5.62 16.12L4.98 14.91L4.57 13.60L2.41 13.44L2.41 10.56L4.57 10.40L4.98 9.09L5.62 7.88L4.20 6.24L6.24 4.20L7.88 5.62L9.09 4.98L10.40 4.57L10.56 2.41L13.44 2.41L13.60 4.57L14.91 4.98L16.12 5.62L17.76 4.20L19.80 6.24L18.38 7.88Z M15.2 12a3.2 3.2 0 1 1-6.4 0a3.2 3.2 0 1 1 6.4 0Z',plus:'M12 5v14M5 12h14',arrow:'M9 5l7 7-7 7',back:'M15 5l-7 7 7 7',camera:'M4 7h4l2-3h4l2 3h4v13H4zM12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6l4 2',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 7v7m0-10v.1',check:'M5 12l4 4L19 6',export:'M12 15V3m-4 4l4-4 4 4M5 12v9h14v-9',calendar:'M4 5h16v16H4zM8 3v4m8-4v4M4 10h16',bell:'M6 8a6 6 0 0 1 12 0v7l2 3H4l2-3zM10 21h4',leaf:'M5 20C0 9 9 3 21 3c0 12-5 20-16 17zm0 0L16 8'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID();
const date=v=>new Date(v).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
let state={lesions:[],results:[],current:null,name:'',duration:60};
let page='home',selected=null,stage='setup',draft={},busy=false;
let db;
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(notify.timeout);notify.timeout=setTimeout(()=>$('#toast').style.display='none',4000);}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('tyrosense',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function read(){return new Promise((resolve,reject)=>{const req=db.transaction('data').objectStore('data').get('workspace');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function save(){return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(state,'workspace');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
function patch(){let dots='';for(let y=0;y<7;y++)for(let x=0;x<7;x++){const px=62+x*23,py=35+y*22;dots+=`<path d="M${px-3} ${py+7}l3-12 3 12z" fill="url(#needle)" stroke="#fff" stroke-width=".6"/><ellipse cx="${px}" cy="${py+7}" rx="4" ry="2" fill="#ac81584d"/>`; }return `<svg class="patch" viewBox="0 0 280 230" role="img" aria-label="Illustration of a translucent microneedle patch"><defs><linearGradient id="base" x2="1" y2="1"><stop stop-color="#fff" stop-opacity=".95"/><stop offset=".5" stop-color="#efdeca" stop-opacity=".7"/><stop offset="1" stop-color="#fff" stop-opacity=".85"/></linearGradient><linearGradient id="needle"><stop stop-color="#fff"/><stop offset="1" stop-color="#b98b5e"/></linearGradient></defs><rect x="22" y="12" width="237" height="201" rx="37" fill="#f4e4d3" stroke="#fff" stroke-width="2"/><rect x="28" y="8" width="225" height="197" rx="33" fill="url(#base)" stroke="#fff" stroke-width="2"/><rect x="43" y="20" width="195" height="170" rx="24" fill="#e8c7a73b" stroke="#fff8"/>${dots}<path d="M44 177q0 18 20 18h150" stroke="#fff" stroke-width="2" fill="none"/></svg>`;}
function header(){return `<header class="top"><div><div class="brand"><img src="icon.svg" alt="">TyroSense</div><div class="prototype">Capstone companion · prototype</div></div><div class="top-actions"><button class="icon-btn" data-action="reminders" aria-label="Follow-up reminders">${icon('bell')}</button><button class="icon-btn" id="menu-toggle" data-action="open-menu" aria-label="Open navigation menu" aria-haspopup="dialog" aria-controls="navigation-menu" aria-expanded="false">${icon('menu')}</button></div></header>`;}
function closeMenu(){
  document.getElementById('navigation-menu')?.close();
}
function openMenu(){
  if(document.getElementById('navigation-menu'))return;
  const current={lesion:'lesions',result:'history'}[page]||page;
  const items=[
    ['home','Home','Your patch and your progress','home'],
    ['lesions','Lesion journal','A story for every spot','lesions'],
    ['test',state.current?'Current test':'New test','Capture and compare your patch','scan'],
    ['history','Result history','See your comparisons over time','history'],
    ['settings','Settings','Your profile and local records','settings']
  ];
  const dialog=modal(`<div class="menu-content"><div class="menu-top"><div class="brand"><img src="icon.svg" alt="">TyroSense</div><button class="icon-btn" data-action="close-menu" aria-label="Close navigation menu" autofocus>${icon('close')}</button></div><div class="menu-intro"><span class="eyebrow">Your companion</span><h1 id="navigation-title">A little care.<br>All in one place.</h1></div><nav class="menu-links" aria-label="Main navigation">${items.map(([p,label,description,i])=>`<button class="menu-link ${current===p?'active':''}" data-page="${p}" ${current===p?'aria-current="page"':''}><span class="tile-icon">${icon(i)}</span><span class="menu-label"><span>${label}</span><small>${description}</small></span>${icon('arrow')}</button>`).join('')}<button class="menu-link" data-action="reminders"><span class="tile-icon">${icon('calendar')}</span><span class="menu-label"><span>Follow-up reminders</span><small>A moment to check in</small></span>${icon('arrow')}</button></nav><p class="menu-footer">Your patch. Your progress. Your perspective.</p></div>`);
  dialog.id='navigation-menu';
  dialog.className='navigation-menu';
  dialog.setAttribute('aria-labelledby','navigation-title');
  const previousOverflow=document.body.style.overflow;
  document.body.style.overflow='hidden';
  $('#menu-toggle')?.setAttribute('aria-expanded','true');
  dialog.addEventListener('close',()=>{
    document.body.style.overflow=previousOverflow;
    $('#menu-toggle')?.setAttribute('aria-expanded','false');
    $('#menu-toggle')?.focus({preventScroll:true});
  },{once:true});
}

const notice=()=>`<p class="note">${icon('info')}<span>Research prototype. Photo comparisons are not a diagnosis. TYR activity estimates require validated calibration.</span></p>`;
function lesionName(lid){return state.lesions.find(l=>l.id===lid)?.name||'Removed lesion';}
function empty(title,description,action,label){return `<div class="card empty"><div class="tile-icon">${icon('leaf')}</div><h3>${title}</h3><p class="sub">${description}</p>${action?`<button class="secondary" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`;}
function resultRow(r){return `<button class="card row between record" data-result="${r.id}"><div class="row"><div class="tile-icon">${icon('scan')}</div><div><h3>${esc(lesionName(r.lesionId))}</h3><p class="small">${date(r.createdAt)}${r.demo?' · Sample data':''}</p></div></div><div><span class="badge">${r.comparison.distance.toFixed(1)} RGB</span></div></button>`;}
function home(){const latest=state.results.at(-1);return `<div class="greeting"><span class="eyebrow">A little care, over time</span><span class="date">${new Date().toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span></div><h1>${state.name?`Hi, ${esc(state.name)}.<br>`:''}Your skin.<br>A clearer perspective.</h1><p class="sub">A place for your patch readings<br>and the changes you want to keep track of.</p><div class="hero hero--home"><span class="hero-tag"><span class="dot"></span>Your patch. Your progress.</span>${patch()}</div><div class="hero-caption"><span>CAPTURE</span><span>·</span><span>COMPARE</span><span>·</span><span>KEEP TRACK</span></div><button class="primary" data-page="test">${icon(state.current?'clock':'plus')}${state.current?'Continue current test':'Start a new test'}${icon('arrow')}</button><div class="section-head"><h2>Your overview</h2><button class="text-btn" data-page="history">View history ${'↗'}</button></div>${state.current?`<button class="card row between record" data-page="test"><div class="row"><div class="tile-icon">${icon('clock')}</div><div><h3>Test in progress</h3><p class="small">${esc(lesionName(state.current.lesionId))}</p></div></div><span class="badge" data-countdown>${clock(remainingSeconds(state.current))}</span></button>`:''}${latest?resultRow(latest):`<div class="card row"><div class="tile-icon">${icon('scan')}</div><div><h3>Your first reading starts here</h3><p class="small">Capture a patch to begin your history.</p></div></div>`}<div class="two-col"><button class="card record" data-page="lesions"><div class="tile-icon">${icon('lesions')}</div><p class="small">Lesion journal</p><h3>${state.lesions.length} ${state.lesions.length===1?'lesion':'lesions'} tracked</h3></button><button class="card record" data-action="reminders"><div class="tile-icon">${icon('calendar')}</div><p class="small">A moment to check in</p><h3>Follow-up reminders</h3></button></div>${notice()}`;}
function lesions(){return `<div class="page-title"><span class="eyebrow">Your skin journal</span><h1>One spot.<br>Its own story.</h1><p class="sub">Keep photos and patch readings together, one lesion at a time.</p></div><button class="primary" data-action="add-lesion">${icon('plus')}Register a lesion</button><div class="section-head"><h2>Tracked lesions</h2><span class="small">${state.lesions.length} total</span></div>${state.lesions.length?state.lesions.map(l=>`<button class="card row between record" data-lesion="${l.id}"><div class="row">${l.photos.length?`<img class="thumb" src="${l.photos.at(-1).image}" alt="Lesion photograph">`:`<div class="tile-icon">${icon('lesions')}</div>`}<div><h3>${esc(l.name)}</h3><p class="small">${esc(l.location)} · ${l.photos.length} photos</p></div></div>${icon('arrow')}</button>`).join(''):empty('A place for every spot','Register a lesion with a name and location. You can add photos whenever you need.')} ${notice()}`;}
function lesionView(){const l=state.lesions.find(l=>l.id===selected);if(!l)return lesions();const records=state.results.filter(r=>r.lesionId===l.id);return `<div class="back-title"><button class="icon-btn" data-page="lesions" aria-label="Back to lesions">${icon('back')}</button><h2>${esc(l.name)}</h2></div><span class="eyebrow">${esc(l.location)}</span><h1>A little history.<br>A better perspective.</h1><p class="sub">${esc(l.notes||'Photograph the same area consistently to make your journal easier to review.')}</p><div class="section-head"><h2>Photo journal</h2><label class="text-btn file-label">${icon('plus')} Add photo<input type="file" accept="image/*" capture="environment" id="lesion-photo" aria-label="Add lesion photograph"></label></div>${l.photos.length?`<div class="photo-pair">${l.photos.map(p=>`<figure><img src="${p.image}" alt="Lesion on ${date(p.date)}"><figcaption>${date(p.date)}</figcaption></figure>`).join('')}</div>`:empty('Your first photo','Add a clear photograph to start this lesion’s visual history.')}<div class="section-head"><h2>Patch readings</h2><span class="small">${records.length} saved</span></div>${records.length?records.map(resultRow).reverse().join(''):empty('No patch readings yet','A completed test for this lesion will appear here.')}<button class="primary" data-action="test-lesion">${icon('plus')}Test this lesion</button><label class="field" for="reminder-date">Your chosen follow-up date</label><input class="input" id="reminder-date" type="date" value="${esc(l.reminder||'')}"><button class="secondary spaced" data-action="save-reminder">${icon('calendar')}Save date & download reminder</button>${notice()}`;}
function history(){return `<div class="page-title"><span class="eyebrow">The bigger picture</span><h1>Your progress,<br>all in one place.</h1><p class="sub">Every saved comparison, organized over time.</p></div>${state.results.length?`<label class="field" for="history-filter">Filter by lesion</label><select class="input" id="history-filter"><option value="">All lesions</option>${state.lesions.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select><div id="history-list" class="spaced">${state.results.slice().reverse().map(resultRow).join('')}</div><button class="secondary export" data-action="export">${icon('export')}Download complete history</button>`:empty('Your history is just beginning','Finish a patch comparison and save it here.','start','Start a test')}${notice()}`;}
function steps(active){return `<div class="steps">${['Prepare','Before','Wait','After'].map((s,i)=>`<div class="step ${i<=active?'active':''}"><span>${i<active?'✓':i+1}</span>${s}</div>`).join('')}</div>`;}
function test(){let content='';if(state.current){const t=state.current;const ready=remainingSeconds(t)===0;content=`${steps(ready?3:2)}<div class="center"><span class="status-pill">${icon('clock')}${ready?'Ready for the after photo':'Reaction timer running'}</span></div><div class="hero" style="min-height:190px">${patch()}</div><div class="timer" data-countdown>${clock(remainingSeconds(t))}</div><p class="sub center">${esc(lesionName(t.lesionId))} · ${t.duration}-minute protocol</p><p class="small center spaced">${ready?'Your selected waiting period has elapsed.':'The timer continues when you leave this page.'}</p><div class="card row"><img class="thumb" src="${t.before.image}" alt="Baseline patch"><div><h3>Baseline photo saved</h3><p class="small">${date(t.startedAt)}</p></div><span class="badge">Complete</span></div>${ready||stage==='after'?`${upload('after','Capture after photo',draft.after)}<p class="small spaced">Match the baseline lighting, distance, orientation, and crop. Keep the reaction area centred in both saved photos.</p>${draft.after?`<button class="primary" data-action="compare" ${busy?'disabled':''}>Compare photos ${icon('arrow')}</button>`:''}`:`<button class="primary" disabled>After photo available when timer ends</button><button class="text-btn spaced" data-action="early">Capture early for prototype testing</button>`}<button class="secondary spaced danger" data-action="cancel-test">Cancel this test</button>`;}else if(stage==='before'){content=`${steps(1)}<h1>Capture your<br>starting point.</h1><p class="sub spaced">Use even lighting and place the whole patch inside the square guide. A green outline marks a stable square candidate. Review the crop before using your photo; the centre 40% of that image will be compared.</p>${upload('before','Capture baseline photo',draft.before)}<p class="small spaced">Photos are resized to 1,200 pixels and stored in this browser.</p><button class="primary" data-action="begin-timer" ${!draft.before||busy?'disabled':''}>Save baseline & start timer ${icon('clock')}</button>`;}else{content=`${steps(0)}<h1>A few steps.<br>A little more insight.</h1><p class="sub">Set up a patch comparison for a tracked lesion.</p><label class="field" for="test-lesion">Which lesion are you monitoring?</label><select class="input" id="test-lesion"><option value="">Select a lesion</option>${state.lesions.map(l=>`<option value="${l.id}" ${draft.lesionId===l.id?'selected':''}>${esc(l.name)} · ${esc(l.location)}</option>`).join('')}</select><button class="text-btn" data-action="add-lesion">+ Register a new lesion</button><div class="hero" style="min-height:200px">${patch()}</div><div class="instructions">${['Follow your team’s patch application protocol.','Capture a baseline photo before the reaction period.','Wait for your selected protocol duration.','Capture the after photo, compare, and save.'].map((v,i)=>`<div class="instruction"><span class="number">${i+1}</span><span>${v}</span></div>`).join('')}</div><label class="field" for="duration">Reaction period (team protocol)</label><select class="input" id="duration"><option value="60" ${state.duration===60?'selected':''}>60 minutes</option><option value="15" ${state.duration===15?'selected':''}>15 minutes</option><option value="1" ${state.duration===1?'selected':''}>1 minute · prototype demonstration</option></select><p class="small spaced">Select the duration specified by your team. These options are not validated clinical instructions.</p><button class="primary" data-action="prepare">Continue to baseline photo ${icon('arrow')}</button>`;}return `<div class="back-title"><button class="icon-btn" data-page="home" aria-label="Back home">${icon('back')}</button><h2>${state.current?'Current test':'Start a new test'}</h2></div>${content}${notice()}`;}
function upload(kind,title,photo){return `<button class="upload capture-slot" id="${kind}-photo" data-action="camera-${kind}" data-camera-kind="${kind}">${photo?`<img src="${photo.image}" alt="${title}"><span class="small">Retake photo</span>`:`${icon('camera')}<h3>${title}</h3><span class="small">Open the live camera & alignment guide</span>`}</button><label class="capture-library file-label">Or choose from your photo library<input id="${kind}-library" type="file" accept="image/*" aria-label="Choose ${kind} photo from library"></label>${photo?`<p class="small center" style="margin-top:8px">Centre 40% sampled · ${photo.capture?.squareDetected?'square candidate crop':photo.capture?.source==='live-camera'?'guide crop':'library photo'}</p>`:''}`;}
function launchCamera(kind){
  openCamera({kind,onCapture:async(file,metadata)=>{
    const p=await photo(file);
    draft[kind]={...p,capturedAt:metadata.capturedAt,capture:metadata};
    render();notify('Photo ready.');
  }});
}

function resultView(){const r=state.results.find(r=>r.id===selected)||draft.result;if(!r)return history();return `<div class="back-title"><button class="icon-btn" data-page="history" aria-label="Back to history">${icon('back')}</button><h2>Patch comparison</h2></div><span class="eyebrow">${r.demo?'Sample demonstration':esc(lesionName(r.lesionId))}</span><h1>A change,<br>captured.</h1><p class="sub spaced">${date(r.createdAt)} · ${r.elapsedMinutes.toFixed(1)} minutes between photos</p><div class="photo-pair"><figure><img src="${r.before.image}" alt="Before patch"><figcaption>BEFORE · baseline</figcaption></figure><figure><img src="${r.after.image}" alt="After patch"><figcaption>AFTER · reaction</figcaption></figure></div><div class="card"><div class="row between"><h3>Image colour difference</h3><span class="badge">Uncalibrated</span></div><div class="metric">${r.comparison.distance.toFixed(1)} <span style="font-size:13px;letter-spacing:0">RGB units</span></div><div class="row"><span class="swatch" style="background:rgb(${r.comparison.before.join(',')})"></span><span class="small">Before</span><span>→</span><span class="swatch" style="background:rgb(${r.comparison.after.join(',')})"></span><span class="small">After</span></div><p class="small spaced">Euclidean distance between mean RGB values in the central 40% of each photograph (0–441.7). Lighting, alignment, and camera settings affect this value. It is not a TYR concentration or risk score.</p></div><div class="card row"><div class="tile-icon">${icon('scan')}</div><div><h3>TYR activity</h3><p class="small">Pending validated calibration</p></div></div>${r.early?'<div class="inline-notice">Captured before the selected waiting period ended. Prototype test only.</div>':''}${draft.result===r?`<button class="primary" data-action="save-result">${icon('check')}Save to lesion history</button>`:`<button class="secondary" data-action="export-result">${icon('export')}Download this record</button>`}${notice()}`;}
function settings(){return `<div class="page-title"><span class="eyebrow">Make it yours</span><h1>A little about<br>your workspace.</h1></div><div class="card"><h3>Your profile</h3><label class="field" for="profile-name">First name (optional)</label><input id="profile-name" class="input" value="${esc(state.name)}" maxlength="40" placeholder="Your name"><button class="secondary spaced" data-action="save-profile">Save profile</button></div><div class="card"><h3>Stored on this device</h3><p class="sub spaced">Photos and records stay in this browser’s local database. They are not uploaded or synced between devices. Clearing browser data removes them.</p><button class="secondary" data-action="export">${icon('export')}Download a backup</button></div><div class="card"><h3>About the analysis</h3><p class="sub spaced">The prototype compares average RGB colour in the centre of two photographs. The live camera can highlight square-shaped candidates as an alignment aid. It does not identify TyroSense patches, correct lighting, estimate enzyme activity, or classify melanoma risk.</p><p class="small">Next research step: a controlled imaging protocol and a validated colour-to-TYR calibration dataset.</p></div><button class="secondary" data-action="demo">Load a labelled sample comparison</button><button class="secondary danger spaced" data-action="clear">Delete all local records</button>${notice()}`;}
function render(){const views={home,lesions,lesion:lesionView,history,test,result:resultView,settings};$('#app').innerHTML=`<div class="shell">${header()}<main>${(views[page]||home)()}</main></div>`;}
function go(p){closeMenu();page=p;render();window.scrollTo({top:0,behavior:'instant'});}
function modal(html){const d=document.createElement('dialog');d.innerHTML=html;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();d.querySelector('[data-close]')?.addEventListener('click',()=>d.close());return d;}
function confirmAction(title,description,action){const d=modal(`<h2>${title}</h2><p class="sub spaced">${description}</p><div class="dialog-actions"><button class="secondary" data-close>Keep it</button><button class="primary" id="confirm">Continue</button></div>`);d.querySelector('#confirm').onclick=async()=>{d.close();try{await action();}catch{notify('Could not save. Your browser storage may be full.');}};}
function addLesion(){const d=modal(`<form id="lesion-form"><h2>A new spot to follow</h2><label class="field" for="lesion-name">Lesion name</label><input class="input" id="lesion-name" required maxlength="60" placeholder="e.g. Shoulder mole"><label class="field" for="lesion-location">Body location</label><input class="input" id="lesion-location" required maxlength="80" placeholder="e.g. Left shoulder"><label class="field" for="lesion-notes">Notes (optional)</label><textarea class="input" id="lesion-notes" maxlength="1000" placeholder="Anything you would like to remember"></textarea><div class="dialog-actions"><button type="button" class="secondary" data-close>Cancel</button><button class="primary">Save lesion</button></div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const name=d.querySelector('#lesion-name').value.trim(),location=d.querySelector('#lesion-location').value.trim();if(!name||!location)return;const l={id:id(),name,location,notes:d.querySelector('#lesion-notes').value.trim(),photos:[],createdAt:Date.now(),reminder:''};state.lesions.push(l);try{await save();draft.lesionId=l.id;d.close();render();notify('Lesion registered.');}catch{state.lesions.pop();notify('Unable to save this lesion.');}};}
async function photo(file){if(!file||!file.type.startsWith('image/'))throw Error('Choose an image file.');if(file.size>25*1024*1024)throw Error('Choose an image smaller than 25 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,1200/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,c.width,c.height);const w=Math.max(1,Math.floor(c.width*.4)),h=Math.max(1,Math.floor(c.height*.4));const rgb=meanRGB(ctx.getImageData(Math.floor((c.width-w)/2),Math.floor((c.height-h)/2),w,h).data);return {image:c.toDataURL('image/jpeg',.8),rgb,capturedAt:Date.now()};}finally{URL.revokeObjectURL(url);}}
function download(name,data,type='application/json'){const blob=new Blob([data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function report(results=state.results){return JSON.stringify({app:'TyroSense capstone prototype',exportedAt:new Date().toISOString(),analysis:'Uncalibrated central-region RGB distance. Not TYR concentration or diagnosis.',lesions:state.lesions,results},null,2);}
function reminders(){const items=state.lesions.filter(l=>l.reminder).sort((a,b)=>a.reminder.localeCompare(b.reminder));modal(`<h2>A moment to check in</h2><p class="sub spaced">Choose a lesion’s follow-up date in its journal. Download a calendar file to receive reminders through your calendar app.</p>${items.length?items.map(l=>`<div class="card"><h3>${esc(l.name)}</h3><p class="small">${esc(l.reminder)}</p></div>`).join(''):'<p class="small spaced">No follow-up dates set yet.</p>'}<button class="primary" data-close>Done</button>`);}
const actions={
'open-menu':openMenu,'close-menu':closeMenu,
'camera-before':()=>launchCamera('before'),'camera-after':()=>launchCamera('after'),
'add-lesion':addLesion,start:()=>go('test'),reminders,
prepare:()=>{const lid=$('#test-lesion').value;if(!lid)return notify('Select or register a lesion first.');draft.lesionId=lid;draft.duration=Number($('#duration').value);stage='before';render();},
'begin-timer':async()=>{if(!draft.before)return;const now=Date.now();state.current={id:id(),lesionId:draft.lesionId,before:draft.before,startedAt:now,duration:draft.duration,dueAt:now+draft.duration*60000};try{await save();stage='wait';draft={};render();}catch{state.current=null;throw Error('Could not save the baseline.');}},
early:()=>confirmAction('Capture before the timer ends?','This will be marked as an early prototype capture in the saved record.',()=>{stage='after';draft.early=true;render();}),
'cancel-test':()=>confirmAction('Cancel this test?','The current baseline and timer will be removed. Saved results will remain.',async()=>{state.current=null;await save();stage='setup';draft={};render();}),
compare:()=>{const t=state.current;if(!t||!draft.after)return;draft.result={id:t.id,lesionId:t.lesionId,before:t.before,after:draft.after,createdAt:Date.now(),elapsedMinutes:(draft.after.capturedAt-t.startedAt)/60000,early:draft.after.capturedAt<t.dueAt,comparison:compareRGB(t.before.rgb,draft.after.rgb)};selected=null;go('result');},
'save-result':async()=>{const r=draft.result;if(!r)return;const old=state.current;state.results.push(r);state.current=null;try{await save();selected=r.id;draft={};stage='setup';render();notify('Comparison saved to your history.');}catch{state.results.pop();state.current=old;throw Error('Unable to save.');}},
'save-profile':async()=>{state.name=$('#profile-name').value.trim();await save();render();notify('Profile saved.');},
'export':()=>download('tyrosense-history.json',report()),
'export-result':()=>{const r=state.results.find(r=>r.id===selected);if(r)download('tyrosense-comparison.json',report([r]));},
clear:()=>confirmAction('Delete your local workspace?','This permanently removes all photos, readings, lesions, and the current timer from this browser. Download a backup first if needed.',async()=>{state={lesions:[],results:[],current:null,name:'',duration:60};await save();draft={};selected=null;stage='setup';go('home');notify('Local records deleted.');}),
 'test-lesion':()=>{draft.lesionId=selected;go('test');},
 'save-reminder':async()=>{const l=state.lesions.find(l=>l.id===selected);const value=$('#reminder-date').value;l.reminder=value;await save();if(!value)return notify('Follow-up date cleared.');const stamp=value.replaceAll('-','');const dt=new Date(value+'T12:00:00');dt.setDate(dt.getDate()+1);const end=[dt.getFullYear(),String(dt.getMonth()+1).padStart(2,'0'),String(dt.getDate()).padStart(2,'0')].join('');const clean=l.name.replace(/[\n\r,;\\]/g,' ');download('tyrosense-follow-up.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//TyroSense//Companion//EN','BEGIN:VEVENT',`UID:${l.id}@tyrosense`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;VALUE=DATE:${stamp}`,`DTEND;VALUE=DATE:${end}`,`SUMMARY:TyroSense follow-up - ${clean}`,'DESCRIPTION:Your chosen lesion journal follow-up.','BEGIN:VALARM','TRIGGER:-PT9H','ACTION:DISPLAY','DESCRIPTION:TyroSense follow-up','END:VALARM','END:VEVENT','END:VCALENDAR',''].join('\r\n'),'text/calendar');notify('Date saved. Import the file into your calendar.');},
 demo:async()=>{if(state.results.some(r=>r.demo))return notify('The sample is already in your history.');const l={id:id(),name:'Sample lesion',location:'Demonstration only',notes:'Synthetic sample photos, not a patient record.',photos:[],createdAt:Date.now()};const sample=(after)=>{const c=document.createElement('canvas');c.width=c.height=400;const ctx=c.getContext('2d');ctx.fillStyle='#d9b391';ctx.fillRect(0,0,400,400);ctx.fillStyle='#ebccb0';ctx.beginPath();ctx.roundRect(65,65,270,270,35);ctx.fill();if(after){const g=ctx.createRadialGradient(200,200,10,200,200,110);g.addColorStop(0,'#a1632c');g.addColorStop(1,'#ebccb0');ctx.fillStyle=g;ctx.fillRect(80,80,240,240);}for(let x=95;x<330;x+=30)for(let y=95;y<330;y+=30){ctx.beginPath();ctx.arc(x,y,3,0,7);ctx.strokeStyle='#fff9';ctx.stroke();}ctx.fillStyle='#493c30';ctx.font='14px sans-serif';ctx.fillText('SYNTHETIC SAMPLE',120,375);return {image:c.toDataURL('image/jpeg'),rgb:meanRGB(ctx.getImageData(120,120,160,160).data),capturedAt:Date.now()};};const b=sample(false),a=sample(true);state.lesions.push(l);state.results.push({id:id(),lesionId:l.id,before:b,after:a,createdAt:Date.now(),elapsedMinutes:60,demo:true,comparison:compareRGB(b.rgb,a.rgb)});try{await save();go('history');notify('Labelled synthetic sample added.');}catch{state.lesions.pop();state.results.pop();throw Error();}}
};
document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target||target.disabled)return;const {page:p,action,result,lesion}=target.dataset;if(target.closest('#navigation-menu'))closeMenu();if(p){if(p==='test'&&!state.current&&!draft.before)stage='setup';go(p);}else if(result){selected=result;draft.result=null;go('result');}else if(lesion){selected=lesion;go('lesion');}else if(action&&actions[action]){if(busy)return;busy=true;try{await actions[action]();}catch(error){notify(error.message||'Unable to save. Browser storage may be full.');}finally{busy=false;}}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='history-filter'){const list=state.results.filter(r=>!el.value||r.lesionId===el.value);$('#history-list').innerHTML=list.length?list.slice().reverse().map(resultRow).join(''):empty('No readings for this lesion','Completed patch comparisons will appear here.');return;}if(!['before-library','after-library','lesion-photo'].includes(el.id)||!el.files[0])return;try{notify('Preparing your photo…');const p=await photo(el.files[0]);if(el.id==='lesion-photo'){const l=state.lesions.find(l=>l.id===selected);l.photos.push({id:id(),date:Date.now(),image:p.image});try{await save();}catch(error){l.photos.pop();throw error;}}else{draft[el.id.split('-')[0]]={...p,capture:{source:'library',squareDetected:false}};}render();notify('Photo ready.');}catch(error){notify(error.message||'Could not read the photo. Try a JPEG or PNG.');}});
setInterval(()=>{if(!state.current)return;const seconds=remainingSeconds(state.current);document.querySelectorAll('[data-countdown]').forEach(el=>el.textContent=clock(seconds));if(!seconds&&page==='test'&&stage!=='after'&&!$('#after-photo')){stage='after';render();notify('Your selected waiting period is complete.');}},1000);
try{db=await openDB();state=(await read())||state;render();}catch{$('#app').innerHTML='<div class="shell"><main><h1>Local storage is unavailable.</h1><p class="sub">Enable browser storage or open TyroSense in a regular browser window to save photographs and results.</p></main></div>';}
